class TopWordsTest(unittest.TestCase):
    def test_counts_case_insensitively(self):
        self.assertEqual(top_words("The the THE cat", 2), [("the", 3), ("cat", 1)])

    def test_splits_on_non_letters(self):
        self.assertEqual(top_words("don't stop, don't", 3), [("don", 2), ("t", 2), ("stop", 1)])

    def test_ties_sorted_alphabetically(self):
        self.assertEqual(top_words("b a c", 3), [("a", 1), ("b", 1), ("c", 1)])

    def test_count_beats_alphabet(self):
        self.assertEqual(top_words("z z a", 1), [("z", 2)])

    def test_fewer_distinct_than_k_returns_all(self):
        self.assertEqual(top_words("hi hi", 5), [("hi", 2)])

    def test_empty_text(self):
        self.assertEqual(top_words("", 3), [])

    def test_non_ascii_letters_separate(self):
        self.assertEqual(top_words("café café", 5), [("caf", 2)])

    def test_k_below_one_raises(self):
        for k in [0, -1]:
            with self.subTest(k=k):
                with self.assertRaises(ValueError):
